def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Check if someone has already won
        if a_points >= 3 and b_points < 3:
            # A is at 40 and B hasn't reached 40, A wins on next point
            if a_points > b_points:
                return "Game A"
        if b_points >= 3 and a_points < 3:
            # B is at 40 and A hasn't reached 40, B wins on next point
            if b_points > a_points:
                return "Game B"

        # At 40-40 (deuce), next point wins the game
        if a_points >= 3 and b_points >= 3 and a_points == b_points:
            if point == 'A':
                return "Game A"
            elif point == 'B':
                return "Game B"

        # Award the point
        if point == 'A':
            a_points += 1
        elif point == 'B':
            b_points += 1

    # Convert points to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle deuce/40-40 case
    if a_points >= 3 and b_points >= 3:
        return "40-40"

    # Handle regular scoring (cap at 3 for display purposes)
    a_display = min(a_points, 3)
    b_display = min(b_points, 3)

    return f"{score_map[a_display]}-{score_map[b_display]}"

def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Award the point
        if point == 'A':
            a_points += 1
        elif point == 'B':
            b_points += 1

        # Check win conditions after awarding the point
        # At 40-40 (deuce), next point wins the game
        if a_points >= 3 and b_points >= 3:
            if a_points > b_points:
                return "Game A"
            elif b_points > a_points:
                return "Game B"
        # A reaches 40+ and is ahead by 2+ points from 40-40, or A at 4+ with B at 0-2
        elif a_points >= 4 and b_points < a_points:
            return "Game A"
        elif b_points >= 4 and a_points < b_points:
            return "Game B"

    # Convert points to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle deuce/40-40 case
    if a_points >= 3 and b_points >= 3:
        return "40-40"

    # Handle regular scoring (cap at 3 for display purposes)
    a_display = min(a_points, 3)
    b_display = min(b_points, 3)

    return f"{score_map[a_display]}-{score_map[b_display]}"
